import{d as T,C as l,o as S,c as A,a3 as a,E as e,j as t,a as i}from"./chunks/framework.Q4yG9rk_.js";const N=JSON.parse('{"title":"庄子·山木","description":"从山木与不鸣之雁的对照，到虚舟、复朴与淡若水之交，理解庄子如何回应材用、名位与人情的牵累。","frontmatter":{"title":"庄子·山木","description":"从山木与不鸣之雁的对照，到虚舟、复朴与淡若水之交，理解庄子如何回应材用、名位与人情的牵累。","category":"guide","aliases":["山木","庄子山木","zhuangzi chapter 20"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-20.md","filePath":"daoism/zhuang-zi/chapter-20.md","lastUpdated":1792641266000}'),C={name:"daoism/zhuang-zi/chapter-20.md"},R=T({...C,setup(V){const o=[{id:"sm_mat_s1",label:"大木以不材得终其天年",sentences:[["庄子行于山中，见大木，枝叶盛茂。"],["伐木者止其旁而不取也。问其故，曰：「无所可用。」"],["庄子曰：「此木以",{text:"不材",glossary:"sm_mat_bucai"},"得",{text:"终其天年",glossary:"sm_mat_tiannian"},"。」"]]},{id:"sm_mat_s2",label:"故人杀不能鸣之雁",sentences:[["夫子出于山，舍于故人之家。故人喜，命",{text:"竖子",glossary:"sm_mat_shuzi"},"杀雁而烹之。"],["竖子请曰：「其一能鸣，其一不能鸣，",{text:"请奚杀",glossary:"sm_mat_xisha"},"？」主人曰：「杀不能鸣者。」"]]},{id:"sm_mat_s3",label:"先生将何处：材与不材之间",sentences:[["明日，弟子问于庄子曰：「昨日山中之木，以不材得终其天年；今主人之雁，以不材死。先生将何处？」"],["庄子笑曰：「周将处乎材与不材之间。材与不材之间，",{text:"似之而非也",glossary:"sm_mat_sizhi"},"，故",{text:"未免乎累",glossary:"sm_mat_lei"},"。"]]},{id:"sm_mat_s4",label:"乘道德而浮游：物物而不物于物",sentences:[["若夫",{text:"乘道德而浮游",glossary:"sm_mat_fuyou"},"则不然，",{text:"无誉无訾",glossary:"sm_mat_yuzi"},"，",{text:"一龙一蛇",glossary:"sm_mat_longshe"},"，与时俱化，而",{text:"无肯专为",glossary:"sm_mat_zhuanwei"},"。"],["一上一下，",{text:"以和为量",glossary:"sm_mat_heliang"},"，浮游乎",{text:"万物之祖",glossary:"sm_mat_wuzu"},"。"],[{text:"物物而不物于物",glossary:"sm_mat_wuwu"},"，则胡可得而累邪！此神农、黄帝之法则也。"]]},{id:"sm_mat_s5",label:"万物之情：胡可得而必乎哉",sentences:[["若夫万物之情，",{text:"人伦之传",glossary:"sm_mat_renlun"},"则不然：合则离，成则毁，",{text:"廉则挫",glossary:"sm_mat_liancuo"},"，尊则议，有为则亏，贤则谋，",{text:"不肖则欺",glossary:"sm_mat_buxiao"},"。"],[{text:"胡可得而必乎哉",glossary:"sm_mat_bihu"},"！悲夫，弟子",{text:"志之",glossary:"sm_mat_zhizhi"},"，其唯",{text:"道德之乡",glossary:"sm_mat_daoxiang"},"乎！」"]]}],m=[{id:"sm_mat_bucai",term:"不材",pinyin:"bù cái",meaning:"不成材、不适于某种用途。大木不能供伐木者取用，雁不能鸣而被认为无用；两者的判定都依具体用途而来，不是对生命全部价值的判断。"},{id:"sm_mat_tiannian",term:"终其天年",pinyin:"zhōng qí tiān nián",meaning:"终尽自然所赋的年寿。此处指大木不因取材而遭砍伐，不宜理解成已经精确知道它最终活了多少年。"},{id:"sm_mat_shuzi",term:"竖子",pinyin:"shù zǐ",meaning:"童仆、年轻仆役。此处不是辱骂用语。"},{id:"sm_mat_xisha",term:"请奚杀",pinyin:"qǐng xī shā",meaning:"请问杀哪一只？奚：哪一个。"},{id:"sm_mat_sizhi",term:"似之而非也",pinyin:"sì zhī ér fēi yě",meaning:"看似接近所求的通达，却还不是。结合下文，批评把材与不材之间固定成保全之策。"},{id:"sm_mat_lei",term:"未免乎累",pinyin:"wèi miǎn hū lèi",meaning:"仍不能免于牵累、拘系。累在此指外在处境与执持造成的拖累，不只指身体疲劳。"},{id:"sm_mat_fuyou",term:"乘道德而浮游",pinyin:"chéng dào dé ér fú yóu",meaning:"依道与德而自在游行。乘联系凭依、乘御理解；道德不是现代日常义的道德规范，也不宜解释为把道当作供自我控制的工具。"},{id:"sm_mat_yuzi",term:"无誉无訾",pinyin:"wú yù wú zǐ",meaning:"誉：称赞；訾：非议、诋毁。可联系不以毁誉立己、不困于毁誉理解，不保证世间无人称赞或批评。"},{id:"sm_mat_longshe",term:"一龙一蛇",pinyin:"yī lóng yī shé",meaning:"时如龙，时如蛇，借显隐、升潜的变化说明不固守一种形态。不是现实中变成动物。"},{id:"sm_mat_zhuanwei",term:"无肯专为",pinyin:"wú kěn zhuān wéi",meaning:"不肯固执于一种作为。不将某种方法永久立为唯一选择。"},{id:"sm_mat_heliang",term:"以和为量",pinyin:"yǐ hé wéi liàng",meaning:"以和适、协调作为尺度。量：衡量的标准，不必只理解成消除一切分歧。"},{id:"sm_mat_wuzu",term:"万物之祖",pinyin:"wàn wù zhī zǔ",meaning:"万物的根本、本源，联系道理解，不指一个有明确谱系的祖先。"},{id:"sm_mat_wuwu",term:"物物而不物于物",pinyin:"wù wù ér bù wù yú wù",meaning:"应接、处置事物，而不反被事物役使。前后有主动与被动的区别，但不宜直接套成自我绝对统治外物的主客二分。"},{id:"sm_mat_renlun",term:"人伦之传",pinyin:"rén lún zhī chuán",meaning:"人际关系中的传习、流转等，具体训释有空间。此处引出世间聚散、得失与相互评价。"},{id:"sm_mat_liancuo",term:"廉则挫",pinyin:"lián zé cuò",meaning:"廉可联系廉直、棱角分明，亦有廉洁之解；挫：受挫折、折损。不仅限于现代廉政意义。"},{id:"sm_mat_buxiao",term:"不肖则欺",pinyin:"bù xiào zé qī",meaning:"不贤、不能者又可能被欺侮。不肖：不贤、不才。与贤则谋相对，说明两端都不能保证安全。"},{id:"sm_mat_bihu",term:"胡可得而必乎哉",pinyin:"hú kě dé ér bì hū zāi",meaning:"怎么能取得必然的保证呢？必：确定、保证。不等于任何风险都完全不能判断。"},{id:"sm_mat_zhizhi",term:"志之",pinyin:"zhì zhī",meaning:"记住它。志联系记忆、记取理解。"},{id:"sm_mat_daoxiang",term:"道德之乡",pinyin:"dào dé zhī xiāng",meaning:"依道与德而游的境域，以乡作譬喻，不是可以在地图上寻找的地方。"}],p=[{id:"sm_boat_s1",label:"鲁侯之忧：除患之术浅矣",sentences:[[{text:"市南宜僚",glossary:"sm_boat_yiliao"},"见鲁侯，鲁侯有忧色。市南子曰：「君有忧色，何也？」"],["鲁侯曰：「吾学先王之道，修先君之业；吾敬鬼尊贤，亲而行之，",{text:"无须臾离居",glossary:"sm_boat_xuyu"},"。然不免于患，吾是以忧。」"],["市南子曰：「君之除患之术浅矣！"]]},{id:"sm_boat_s2",label:"丰狐文豹：鲁国独非君之皮邪",sentences:[["夫",{text:"丰狐文豹",glossary:"sm_boat_hubao"},"，栖于山林，伏于岩穴，静也；夜行昼居，戒也；虽饥渴隐约，犹且",{text:"胥疏",glossary:"sm_boat_xushu"},"于江湖之上而求食焉，定也。"],["然且不免于",{text:"罔罗机辟",glossary:"sm_boat_wangluo"},"之患，是何罪之有哉？其皮为之灾也。今鲁国独非君之皮邪？"]]},{id:"sm_boat_s3",label:"建德之国：去国捐俗",sentences:[["吾愿君",{text:"刳形去皮",glossary:"sm_boat_kuxing"},"，",{text:"洒心去欲",glossary:"sm_boat_saxin"},"，而游于无人之野。"],["南越有邑焉，名为",{text:"建德之国",glossary:"sm_boat_jiande"},"。其民愚而朴，少私而寡欲；知作而不知藏，与而不求其报；不知义之所适，不知礼之所将。"],[{text:"猖狂妄行，乃蹈乎大方",glossary:"sm_boat_dafang"},"。其生可乐，其死可葬。吾愿君",{text:"去国捐俗",glossary:"sm_boat_quguo"},"，与道相辅而行。」"]]},{id:"sm_boat_s4",label:"无舟车、无粮食：无形倨，寡君之欲",sentences:[["君曰：「彼其道远而险，又有江山，我无舟车，奈何？」"],["市南子曰：「君",{text:"无形倨，无留居",glossary:"sm_boat_xingju"},"，以为君车。」"],["君曰：「彼其道幽远而无人，吾谁与为邻？吾无粮，我无食，安得而至焉？」"],["市南子曰：「少君之费，寡君之欲，虽无粮而乃足。"]]},{id:"sm_boat_s5",label:"有人者累，见有于人者忧",sentences:[["君其涉于江而浮于海，望之而不见其崖，愈往而不知其所穷。送君者皆自崖而反。君自此远矣！"],["故",{text:"有人者累，见有于人者忧",glossary:"sm_boat_youren"},"。故尧非有人，非见有于人也。"],["吾愿去君之累，除君之忧，而独与道游于",{text:"大莫之国",glossary:"sm_boat_damo"},"。"]]},{id:"sm_boat_s6",label:"虚船与实船：人能虚己以游世",sentences:[[{text:"方舟",glossary:"sm_boat_fangzhou"},"而济于河，有虚船来触舟，虽有",{text:"褊心",glossary:"sm_boat_bianxin"},"之人不怒。"],["有一人在其上，则",{text:"呼张歙之",glossary:"sm_boat_zhangxi"},"。一呼而不闻，再呼而不闻，于是三呼邪，则必以恶声随之。"],["向也不怒而今也怒，向也虚而今也实。人能",{text:"虚己以游世",glossary:"sm_boat_xuji"},"，其孰能害之！」"]]}],g=[{id:"sm_boat_yiliao",term:"市南宜僚",pinyin:"shì nán yí liáo",meaning:"人名，篇中又称市南子。宜僚亦见于其他古代记载，不宜简单断言为纯粹虚构；此处按寓言中的论道人物阅读。"},{id:"sm_boat_xuyu",term:"无须臾离居",pinyin:"wú xū yú lí jū",meaning:"片刻不离其所奉行。须臾：极短时间；离居的具体解释有空间，整体强调鲁侯持续践行。"},{id:"sm_boat_hubao",term:"丰狐文豹",pinyin:"fēng hú wén bào",meaning:"毛皮丰美的狐狸、花纹美丽的豹子。丰与文突出其被猎取的价值。"},{id:"sm_boat_xushu",term:"胥疏",pinyin:"xū shū",meaning:"疏远、伺察或从容游行等，有不同解释。语境中突出它们觅食时仍谨慎自持，不强定为完全无戒备。"},{id:"sm_boat_wangluo",term:"罔罗机辟",pinyin:"wǎng luó jī bì",meaning:"捕猎用的网罗、机关与陷阱。罔联系网理解；机辟的具体器物解释有差异。"},{id:"sm_boat_kuxing",term:"刳形去皮",pinyin:"kū xíng qù pí",meaning:"刳：剖开、剖空。承接皮为之灾，以去形去皮喻卸除名位与自我执持，不是要求实际伤害身体。"},{id:"sm_boat_saxin",term:"洒心去欲",pinyin:"sǎ xīn qù yù",meaning:"洗涤心中执持，减少欲求。洒联系洗涤理解，读音有依通假处理者。"},{id:"sm_boat_jiande",term:"建德之国",pinyin:"jiàn dé zhī guó",meaning:"寓言中的理想国度，以质朴、少私寡欲、不求回报描写其生活，不宜按真实地理坐实。"},{id:"sm_boat_dafang",term:"猖狂妄行，乃蹈乎大方",pinyin:"chāng kuáng wàng xíng, nǎi dǎo hū dà fāng",meaning:"不拘通常成法地自在而行，却契合大道。猖狂不直接用现代贬义理解；大方联系大道、广大之道理解。不等于任意伤害他人。"},{id:"sm_boat_quguo",term:"去国捐俗",pinyin:"qù guó juān sú",meaning:"离开国土，舍弃世俗习尚。寓言中确有离去的行动方向，也可引申为解除对君位与俗见的执持。"},{id:"sm_boat_xingju",term:"无形倨，无留居",pinyin:"wú xíng jù, wú liú jū",meaning:"不以形貌、身份自高，不固着于所居。具体训释有差异；在舟车问答中将外在旅途转向内在执持。"},{id:"sm_boat_youren",term:"有人者累，见有于人者忧",pinyin:"yǒu rén zhě lèi, jiàn yǒu yú rén zhě yōu",meaning:"占有人、役属人者受累，被人占有、役属者生忧。见为被动标志。不是一切关怀、友谊与责任都应取消。"},{id:"sm_boat_damo",term:"大莫之国",pinyin:"dà mò zhī guó",meaning:"广大寂漠的境域；莫常联系漠理解。指向与道同游，不必直接等同于彻底虚无。"},{id:"sm_boat_fangzhou",term:"方舟",pinyin:"fāng zhōu",meaning:"并联的船、两舟相并。此处不指现代语境中的某种特定方舟。"},{id:"sm_boat_bianxin",term:"褊心",pinyin:"biǎn xīn",meaning:"心胸狭窄。来稿作囗惼心，存在缺字或字形异常，此处整理为褊心；如项目有统一底本，应再据底本校定。"},{id:"sm_boat_zhangxi",term:"呼张歙之",pinyin:"hū zhāng xī zhī",meaning:"呼喊对方操舟避让。张歙本有张开、收合之义，具体操舟方式不强定。"},{id:"sm_boat_xuji",term:"虚己以游世",pinyin:"xū jǐ yǐ yóu shì",meaning:"不以自我执持、名位与争胜占满自身，而在世间应接。寓言强调减少对抗与牵累，不保证免受一切实际伤害。"}],_=[{id:"sm_bell_s1",label:"北宫奢赋敛为钟：子何术之设",sentences:[[{text:"北宫奢",glossary:"sm_bell_she"},"为卫灵公",{text:"赋敛",glossary:"sm_bell_fulian"},"以为钟，为坛乎郭门之外。三月而成",{text:"上下之县",glossary:"sm_bell_xuan"},"。"],["王子庆忌见而问焉，曰：「子何术之设？」"]]},{id:"sm_bell_s2",label:"一之间无敢设：既雕既琢，复归于朴",sentences:[["奢曰：「",{text:"一之间无敢设也",glossary:"sm_bell_yijian"},"。奢闻之：『既雕既琢，",{text:"复归于朴",glossary:"sm_bell_fupu"},"。』"],[{text:"侗乎其无识",glossary:"sm_bell_tonghu"},"，",{text:"傥乎其怠疑",glossary:"sm_bell_tanghu"},"。",{text:"萃乎芒乎",glossary:"sm_bell_cuimang"},"，其送往而迎来。"]]},{id:"sm_bell_s3",label:"来者勿禁，往者勿止",sentences:[["来者勿禁，往者勿止。从其",{text:"强梁",glossary:"sm_bell_qiangliang"},"，随其",{text:"曲傅",glossary:"sm_bell_qufu"},"，",{text:"因其自穷",glossary:"sm_bell_ziqiong"},"。"],["故朝夕赋敛而",{text:"毫毛不挫",glossary:"sm_bell_bucuo"},"，而况有",{text:"大涂",glossary:"sm_bell_datu"},"者乎！」"]]}],h=[{id:"sm_bell_she",term:"北宫奢",pinyin:"běi gōng shē",meaning:"篇中的卫国人物，为卫灵公筹集铸钟所需。其完整身世不详，不在此确定为虚构或作具体官职考证。"},{id:"sm_bell_fulian",term:"赋敛",pinyin:"fù liǎn",meaning:"征收、筹集财物。这里为铸钟而进行，不宜直接据此复原全部征税制度。"},{id:"sm_bell_xuan",term:"上下之县",pinyin:"shàng xià zhī xuán",meaning:"县通悬，联系钟的悬设、悬钟之具或整套钟悬理解。不强定为上下两层架子的具体样式。"},{id:"sm_bell_yijian",term:"一之间无敢设也",pinyin:"yī zhī jiān wú gǎn shè yě",meaning:"疑难句，常联系专一、不夹杂人为机巧理解。结合下文，否定把刻意设术视为根本，不等于全无安排与行动。"},{id:"sm_bell_fupu",term:"复归于朴",pinyin:"fù guī yú pǔ",meaning:"返回质朴。与既雕既琢相接，提示经历加工后不固执于加工之迹，不直接等于拒绝所有技能。"},{id:"sm_bell_tonghu",term:"侗乎其无识",pinyin:"tóng hū qí wú shí",meaning:"侗：无知、未分辨的样子。可联系不以智巧自矜理解，不证明北宫奢实际毫无知识。"},{id:"sm_bell_tanghu",term:"傥乎其怠疑",pinyin:"tǎng hū qí dài yí",meaning:"疑难词组，联系舒放、不拘于精细筹计等理解；不将怠疑强定为完全没有任何忧虑。"},{id:"sm_bell_cuimang",term:"萃乎芒乎",pinyin:"cuì hū máng hū",meaning:"形容聚会、茫然或不显形迹的状态，具体训释有差异。与送往迎来连读。"},{id:"sm_bell_qiangliang",term:"强梁",pinyin:"qiáng liáng",meaning:"强硬、强悍。此处说面对强硬者不一味与之对抗，不等于强硬行为本身受到赞许。"},{id:"sm_bell_qufu",term:"曲傅",pinyin:"qū fù",meaning:"曲折附合、曲从等，傅联系附理解。与强梁对举，描写不同来者的情态。"},{id:"sm_bell_ziqiong",term:"因其自穷",pinyin:"yīn qí zì qióng",meaning:"顺循其自身情势，让其自行展开至尽。不是以逼迫使人穷困。"},{id:"sm_bell_bucuo",term:"毫毛不挫",pinyin:"háo máo bù cuò",meaning:"毫毛般的微小损折也没有，可联系自己不受挫损理解。不直接等于史实上无民怨、无阻力或所有人都自愿缴纳。"},{id:"sm_bell_datu",term:"大涂",pinyin:"dà tú",meaning:"大道。涂通途；由具体事务中的顺应，推向更广大的通达。"}],y=[{id:"sm_bird_s1",label:"孔子困于陈蔡：子几死乎，子恶死乎",sentences:[["孔子围于陈蔡之间，七日不火食。",{text:"大公任",glossary:"sm_bird_taigong"},"往",{text:"吊",glossary:"sm_bird_diao"},"之，曰：「子几死乎？」曰：「然。」"],["「子",{text:"恶死",glossary:"sm_bird_wusi"},"乎？」曰：「然。」"]]},{id:"sm_bird_s2",label:"意怠之鸟：不争先，不离群",sentences:[["任曰：「予尝言不死之道。东海有鸟焉，其名曰",{text:"意怠",glossary:"sm_bird_yidai"},"。"],["其为鸟也，",{text:"翂翐",glossary:"sm_bird_fenzhi"},"，而似无能；",{text:"引援而飞，迫胁而栖",glossary:"sm_bird_yinyuan"},"；进不敢为前，退不敢为后；食不敢先尝，必取其",{text:"绪",glossary:"sm_bird_xu"},"。"],["是故其行列不斥，而外人卒不得害，是以免于患。"]]},{id:"sm_bird_s3",label:"直木先伐，甘井先竭",sentences:[["直木先伐，甘井先竭。子其意者",{text:"饰知以惊愚，修身以明汙",glossary:"sm_bird_shizhi"},"，昭昭乎如揭日月而行，故不免也。"],["昔吾闻之大成之人曰：『",{text:"自伐者无功",glossary:"sm_bird_zifa"},"，功成者堕，名成者亏。』孰能去功与名而还与众人！"]]},{id:"sm_bird_s4",label:"道流而不明居：至人不闻",sentences:[["道流而不明居，",{text:"得行而不名处",glossary:"sm_bird_dexing"},"；纯纯常常，乃比于狂；",{text:"削迹捐势",glossary:"sm_bird_xueji"},"，不为功名。"],["是故",{text:"无责于人，人亦无责焉",glossary:"sm_bird_wuze"},"。",{text:"至人不闻",glossary:"sm_bird_buwen"},"，子何喜哉！」"]]},{id:"sm_bird_s5",label:"孔子入泽：入兽不乱群，入鸟不乱行",sentences:[["孔子曰：「善哉！」辞其交游，去其弟子，逃于大泽，",{text:"衣裘褐",glossary:"sm_bird_qiuhe"},"，食",{text:"杼栗",glossary:"sm_bird_zhuli"},"，入兽不乱群，入鸟不乱行。"],["鸟兽不恶，而况人乎！"]]}],u=[{id:"sm_bird_taigong",term:"大公任",pinyin:"tài gōng rèn",meaning:"篇中的论道人物。大公常读为太公；具体身份不强定。"},{id:"sm_bird_diao",term:"吊",pinyin:"diào",meaning:"慰问。往吊之：前去慰问，并非已经发生死亡后的吊丧。"},{id:"sm_bird_wusi",term:"恶死",pinyin:"wù sǐ",meaning:"厌恶死亡、不愿死，可联系畏死理解。恶读 wù。"},{id:"sm_bird_yidai",term:"意怠",pinyin:"yì dài",meaning:"寓言中的东海鸟。原文突出其似无能、随群、不争先；不据名称建立确定的鸟类学解释。"},{id:"sm_bird_fenzhi",term:"翂翐",pinyin:"fēn zhì",meaning:"飞行迟缓、舒缓或羽翼舒张的样子，训释有差异。结合似无能，不突出迅猛矫健。"},{id:"sm_bird_yinyuan",term:"引援而飞，迫胁而栖",pinyin:"yǐn yuán ér fēi, pò xié ér qī",meaning:"相引相援而飞，相近相依而栖等，具体解释有差异。迫胁不宜只理解成被迫才肯停下，整体突出与群体相依。"},{id:"sm_bird_xu",term:"绪",pinyin:"xù",meaning:"余剩、残余。必取其绪：不争先取食，取其余剩。"},{id:"sm_bird_shizhi",term:"饰知以惊愚，修身以明汙",pinyin:"shì zhī yǐ jīng yú, xiū shēn yǐ míng wū",meaning:"用修饰、显示的智识使愚者惊异，以自身修养显出他人的污浊。批评以才德形成对人的压迫与优越，不是直接否定学习修身。"},{id:"sm_bird_zifa",term:"自伐者无功",pinyin:"zì fá zhě wú gōng",meaning:"自我夸耀者不能据此成就真正的功。伐：夸耀，不作砍伐解。"},{id:"sm_bird_dexing",term:"得行而不名处",pinyin:"dé xíng ér bù míng chǔ",meaning:"得常联系德理解：德得以流行，不据名位自居。保留来稿文字，不直接替换为德。"},{id:"sm_bird_xueji",term:"削迹捐势",pinyin:"xuē jì juān shì",meaning:"消减显露的形迹，舍去权势。不以功名与势位作为自我立足的凭借。"},{id:"sm_bird_wuze",term:"无责于人，人亦无责焉",pinyin:"wú zé yú rén, rén yì wú zé yān",meaning:"不向人责求，人也不向自己责求。责既可涉及责斥，也可涉及要求；不等于任何伤害都不能追责。"},{id:"sm_bird_buwen",term:"至人不闻",pinyin:"zhì rén bù wén",meaning:"至人不以闻达立己、不求显名。闻联系声名、闻达理解，不是没有听觉。"},{id:"sm_bird_qiuhe",term:"衣裘褐",pinyin:"yì qiú hè",meaning:"穿皮衣、粗布衣。衣在此作动词，读 yì；裘不等于粗布。"},{id:"sm_bird_zhuli",term:"杼栗",pinyin:"zhù lì",meaning:"树实，常联系橡实、栗实等理解。不强定全部为同一种果实。"}],b=[{id:"sm_friend_s1",label:"孔子之问：亲交益疏，徒友益散",sentences:[["孔子问",{text:"子桑雽",glossary:"sm_friend_sanghu"},"曰：「吾再逐于鲁，伐树于宋，削迹于卫，穷于商周，围于陈蔡之间。"],["吾犯此数患，亲交益疏，徒友益散，何与？」"]]},{id:"sm_friend_s2",label:"林回弃璧负赤子：彼以利合，此以天属",sentences:[["子桑雽曰：「子独不闻",{text:"假人之亡",glossary:"sm_friend_jiaren"},"与？林回弃千金之璧，",{text:"负赤子而趋",glossary:"sm_friend_chizi"},"。"],["或曰：『为其",{text:"布",glossary:"sm_friend_bu"},"与？赤子之布寡矣；为其累与？赤子之累多矣。弃千金之璧，负赤子而趋，何也？』"],["林回曰：『彼以利合，此以",{text:"天属",glossary:"sm_friend_tianshu"},"也。』"]]},{id:"sm_friend_s3",label:"相弃与相收：君子之交淡若水",sentences:[["夫以利合者，迫穷祸患害相弃也；以天属者，迫穷祸患害",{text:"相收",glossary:"sm_friend_xiangshou"},"也。"],["夫相收之与相弃亦远矣，且君子之交淡若水，小人之交甘若",{text:"醴",glossary:"sm_friend_li"},"。"],["君子淡以亲，小人甘以绝，",{text:"彼无故以合者，则无故以离",glossary:"sm_friend_wugu"},"。」"]]},{id:"sm_friend_s4",label:"孔子归去：其爱益加进",sentences:[["孔子曰：「敬闻命矣！」徐行",{text:"翔佯",glossary:"sm_friend_xiangyang"},"而归，",{text:"绝学捐书",glossary:"sm_friend_juexue"},"，弟子",{text:"无挹于前",glossary:"sm_friend_wuyi"},"，其爱益加进。"]]},{id:"sm_friend_s5",label:"舜告禹：形莫若缘，情莫若率",sentences:[["异日，桑雽又曰：「舜之将死，",{text:"真泠禹",glossary:"sm_friend_zhenling"},"曰：『汝戒之哉！",{text:"形莫若缘，情莫若率",glossary:"sm_friend_yuanshuai"},"。』"],["缘则不离，率则不劳。不离不劳，则",{text:"不求文以待形",glossary:"sm_friend_wenxing"},"。不求文以待形，固",{text:"不待物",glossary:"sm_friend_budai"},"。」"]]}],x=[{id:"sm_friend_sanghu",term:"子桑雽",pinyin:"zǐ sāng hù",meaning:"篇中的论道人物，名的字形有异文。不未经考证便与其他篇章同名或近名人物完全合一。"},{id:"sm_friend_jiaren",term:"假人之亡",pinyin:"jiǎ rén zhī wáng",meaning:"疑难词组，传统有将假作为国名、假人作为该国之人等解释。可先理解为逃亡背景中的故事，不直接把假人释成所有逃亡者的通称。"},{id:"sm_friend_chizi",term:"负赤子而趋",pinyin:"fù chì zǐ ér qū",meaning:"背着婴儿奔走。负：背负；赤子：婴儿；趋：快步走、奔走。"},{id:"sm_friend_bu",term:"布",pinyin:"bù",meaning:"财货、货币等。问者以财富收益衡量婴儿，借此暴露利益计算与亲情的不同。"},{id:"sm_friend_tianshu",term:"天属",pinyin:"tiān shǔ",meaning:"天然的亲属联系、自然亲情。故事以父子关系为例，后文推到不以利为唯一根据的交往；不保证所有血缘关系都实际可靠。"},{id:"sm_friend_xiangshou",term:"相收",pinyin:"xiāng shōu",meaning:"相互收容、扶持、照顾，与相弃相对。"},{id:"sm_friend_li",term:"醴",pinyin:"lǐ",meaning:"甜酒。甘若醴借浓甜比附交往，不是在讲酒的保存期限。"},{id:"sm_friend_wugu",term:"彼无故以合者，则无故以离",pinyin:"bǐ wú gù yǐ hé zhě, zé wú gù yǐ lí",meaning:"无故的训释有讨论空间，可联系缺乏真正根据、深厚根由的结合易离理解。不宜反过来理解成没有功利目的的友情一定会离散。"},{id:"sm_friend_xiangyang",term:"翔佯",pinyin:"xiáng yáng",meaning:"徘徊、从容游行。与徐行相接，写其缓步归去。"},{id:"sm_friend_juexue",term:"绝学捐书",pinyin:"jué xué juān shū",meaning:"断绝所执的学，舍弃书籍。寓言采用强烈的行动描写，可联系放下以学问立己的执持，但不宜改写成原文完全没说弃书。"},{id:"sm_friend_wuyi",term:"无挹于前",pinyin:"wú yì yú qián",meaning:"挹有揖让、退抑等解释，常联系弟子不再拘谨揖让理解。不能仅凭此句断定师生间一切礼节都取消。"},{id:"sm_friend_zhenling",term:"真泠禹",pinyin:"zhēn líng yǔ",meaning:"疑难词组，常联系郑重告诫、嘱咐禹理解；泠亦有其他字形异文。此处保留来稿，建议最终按项目底本校定。"},{id:"sm_friend_yuanshuai",term:"形莫若缘，情莫若率",pinyin:"xíng mò ruò yuán, qíng mò ruò shuài",meaning:"形体行事宜顺循，情感宜循其真实。缘：顺循；率：循、率真等。不等于无条件服从别人或任意宣泄情绪。"},{id:"sm_friend_wenxing",term:"不求文以待形",pinyin:"bù qiú wén yǐ dài xíng",meaning:"不求借文饰来支撑形体、处世形象。文联系修饰、外在仪文理解；待有凭待、应接等解释。"},{id:"sm_friend_budai",term:"不待物",pinyin:"bù dài wù",meaning:"不把自身安顿完全寄托于外物。不等于生命不需要食物、居所与他人帮助。"}],c=[{id:"sm_poverty_s1",label:"庄子过魏王：贫也，非惫也",sentences:[["庄子",{text:"衣大布而补之",glossary:"sm_poverty_dabu"},"，",{text:"正絜系履",glossary:"sm_poverty_xilv"},"而过魏王。"],["魏王曰：「何先生之惫邪？」"],["庄子曰：「贫也，非惫也。士有道德不能行，",{text:"惫",glossary:"sm_poverty_bei"},"也；衣弊履穿，贫也，非惫也，此所谓",{text:"非遭时",glossary:"sm_poverty_zaoshi"},"也。"]]},{id:"sm_poverty_s2",label:"腾猿得大木：揽蔓其枝",sentences:[["王独不见夫腾猿乎？其得",{text:"楠梓豫章",glossary:"sm_poverty_nanzi"},"也，",{text:"揽蔓其枝而王长其间",glossary:"sm_poverty_wangzhang"},"，虽羿、蓬蒙不能",{text:"眄睨",glossary:"sm_poverty_mianni"},"也。"]]},{id:"sm_poverty_s3",label:"腾猿处荆棘：处势不便",sentences:[["及其得",{text:"柘棘枳枸",glossary:"sm_poverty_zhiji"},"之间也，危行侧视，",{text:"振动悼栗",glossary:"sm_poverty_daoli"},"。"],["此筋骨非有加急而不柔也，",{text:"处势不便",glossary:"sm_poverty_chushi"},"，未足以逞其能也。"]]},{id:"sm_poverty_s4",label:"昏上乱相：比干之见剖心",sentences:[["今处",{text:"昏上乱相",glossary:"sm_poverty_hunshang"},"之间而欲无惫，奚可得邪？"],["此比干之",{text:"见剖心",glossary:"sm_poverty_pouxin"},"，徵也夫！」"]]}],f=[{id:"sm_poverty_dabu",term:"衣大布而补之",pinyin:"yì dà bù ér bǔ zhī",meaning:"穿粗布衣，衣服又有补缀。衣作动词，读 yì；大布：粗布。外貌贫困不直接等于才德衰败。"},{id:"sm_poverty_xilv",term:"正絜系履",pinyin:"zhèng xié jì lǚ",meaning:"整理、用绳系好鞋履。絜为疑难字，常联系结绳、绳带理解，字形与读法应依底本校定；系在系结义读 jì。"},{id:"sm_poverty_bei",term:"惫",pinyin:"bèi",meaning:"困惫、困顿衰败。庄子将道德不能行与衣弊履穿区分，不只是在区分心理疲劳与经济收入。"},{id:"sm_poverty_zaoshi",term:"非遭时",pinyin:"fēi zāo shí",meaning:"没有遇到合宜的时世、时机。强调人的遭际与时代条件有关，不单凭贫富判断其成就。"},{id:"sm_poverty_nanzi",term:"楠梓豫章",pinyin:"nán zǐ yù zhāng",meaning:"树木名称，整体描写适合猿猴攀援的大木。豫章常联系樟树等解释，具体树种不在此强定。"},{id:"sm_poverty_wangzhang",term:"揽蔓其枝而王长其间",pinyin:"lǎn màn qí zhī ér wàng zhǎng qí jiān",meaning:"攀援枝条，在其间自在活动、居于优势。王、长联系称王、为长理解；王在此按动词义读 wàng，不必译成支配其他动物。"},{id:"sm_poverty_mianni",term:"眄睨",pinyin:"miǎn nì",meaning:"侧目看、窥视，语境中联系瞄准理解。羿、蓬蒙为传说中的善射者；不宜把寓言夸张直接改成可验证的绝对无敌。"},{id:"sm_poverty_zhiji",term:"柘棘枳枸",pinyin:"zhè jí zhǐ jǔ",meaning:"柘树、荆棘、枳与枸等树木，整体描写不便攀援的杂木荆棘环境。枸在此常读 jǔ，具体植物解释有差异。"},{id:"sm_poverty_daoli",term:"振动悼栗",pinyin:"zhèn dòng dào lì",meaning:"震动、恐惧战栗。悼栗在此联系惧怕理解，不按现代哀悼义解释。"},{id:"sm_poverty_chushi",term:"处势不便",pinyin:"chǔ shì bù biàn",meaning:"所处的条件不利于施展。能力并未必衰退，表现却会受环境限制。"},{id:"sm_poverty_hunshang",term:"昏上乱相",pinyin:"hūn shàng luàn xiàng",meaning:"昏庸的君主、乱政的相臣。相指辅政者，读 xiàng。这里将猿猴的处境转入政治批评。"},{id:"sm_poverty_pouxin",term:"见剖心",pinyin:"jiàn pōu xīn",meaning:"被剖心。见为被动标志；比干之事依古代传说阅读，作为暴政伤害忠直者的明证。徵：证据、验证。"}],q=[{id:"sm_heaven_s1",label:"孔子击木而歌：木声与人声",sentences:[["孔子穷于陈蔡之间，七日不火食。左据槁木，右击槁枝，而歌",{text:"焱氏之风",glossary:"sm_heaven_yanshi"},"，",{text:"有其具而无其数",glossary:"sm_heaven_jushu"},"，有其声而无宫角。"],["木声与人声，",{text:"犁然有当于人之心",glossary:"sm_heaven_liran"},"。"]]},{id:"sm_heaven_s2",label:"颜回窥之：孔子提出四句",sentences:[["颜回",{text:"端拱还目",glossary:"sm_heaven_duangong"},"而窥之。仲尼恐其",{text:"广己而造大，爱己而造哀",glossary:"sm_heaven_guangji"},"也，曰："],["「回，",{text:"无受天损易，无受人益难",glossary:"sm_heaven_sunyi"},"。",{text:"无始而非卒",glossary:"sm_heaven_shizu"},"也，人与天一也。夫今之歌者其谁乎！」"]]},{id:"sm_heaven_s3",label:"无受天损：与之偕逝",sentences:[["回曰：「敢问无受天损易。」"],["仲尼曰：「饥渴寒暑，",{text:"穷桎不行",glossary:"sm_heaven_qiongzhi"},"，天地之行也，",{text:"运物之泄",glossary:"sm_heaven_yunwu"},"也，言与之",{text:"偕逝",glossary:"sm_heaven_xieshi"},"之谓也。"],["为人臣者，不敢去之。执臣之道犹若是，而况乎所以待天乎？」"]]},{id:"sm_heaven_s4",label:"无受人益：爵禄与在外之命",sentences:[["「何谓无受人益难？」"],["仲尼曰：「",{text:"始用四达",glossary:"sm_heaven_sida"},"，爵禄并至而不穷。物之所利，乃非己也，",{text:"吾命有在外者也",glossary:"sm_heaven_za wai"},"。"],["君子不为盗，贤人不为窃，吾若取之何哉？"]]},{id:"sm_heaven_s5",label:"鷾鸸：畏人而在人间",sentences:[["故曰：鸟莫知于",{text:"鷾鸸",glossary:"sm_heaven_yier"},"，",{text:"目之所不宜处不给视",glossary:"sm_heaven_jishi"},"，虽落其实，弃之而走。"],["其畏人也而",{text:"袭诸人间",glossary:"sm_heaven_xiren"},"。社稷存焉尔！」"]]},{id:"sm_heaven_s6",label:"无始而非卒：正而待之",sentences:[["「何谓无始而非卒？」"],["仲尼曰：「化其万物而不知其",{text:"禅",glossary:"sm_heaven_shan"},"之者，焉知其所终？焉知其所始？",{text:"正而待之",glossary:"sm_heaven_zhengdai"},"而已耳。」"]]},{id:"sm_heaven_s7",label:"人与天一：晏然体逝而终",sentences:[["「何谓人与天一邪？」"],["仲尼曰：「有人，天也；有天，亦天也。",{text:"人之不能有天，性也",glossary:"sm_heaven_xing"},"。圣人",{text:"晏然体逝而终",glossary:"sm_heaven_tishi"},"矣！」"]]}],z=[{id:"sm_heaven_yanshi",term:"焱氏之风",pinyin:"yàn shì zhī fēng",meaning:"焱氏的歌风、歌谣。焱氏有异文与不同解释，此处保留来稿，不强定其具体帝王身份。风联系歌风、歌谣理解。"},{id:"sm_heaven_jushu",term:"有其具而无其数",pinyin:"yǒu qí jù ér wú qí shù",meaning:"有发声之具，却不循整齐的节数、曲度。与无宫角相接，突出不受常规乐律拘束，不证明乐声完全没有节奏。"},{id:"sm_heaven_liran",term:"犁然有当于人之心",pinyin:"lí rán yǒu dàng yú rén zhī xīn",meaning:"清楚、畅然地契合人心。犁然的具体训释有差异；当在契合义读 dàng。"},{id:"sm_heaven_duangong",term:"端拱还目",pinyin:"duān gǒng huán mù",meaning:"端身拱手，转目而看。还目联系回转目光理解，读音可依底本处理。"},{id:"sm_heaven_guangji",term:"广己而造大，爱己而造哀",pinyin:"guǎng jǐ ér zào dà, ài jǐ ér zào āi",meaning:"孔子担心颜回推崇自己而过度放大，或爱惜自己而陷入哀伤。己所指是孔子，不宜直接改成颜回炫耀自己。"},{id:"sm_heaven_sunyi",term:"无受天损易，无受人益难",pinyin:"wú shòu tiān sǔn yì, wú shòu rén yì nán",meaning:"不以自然遭际损害自身的安顿，相对容易；不被人为的增益、爵禄所牵引，更难。下文依偕逝与不妄取展开，不是承诺不再饥渴受寒。"},{id:"sm_heaven_shizu",term:"无始而非卒",pinyin:"wú shǐ ér fēi zú",meaning:"常理解为没有不同时关联终结的开始，终始在变化中相续。句式与义理有解释空间，不直接译成没有开始也没有终结。"},{id:"sm_heaven_qiongzhi",term:"穷桎不行",pinyin:"qióng zhì bù xíng",meaning:"困穷、受拘束而不能行。桎本指足械，此处联系拘困理解。"},{id:"sm_heaven_yunwu",term:"运物之泄",pinyin:"yùn wù zhī xiè",meaning:"万物运行、流转的展开。泄联系流行、发泄等，具体训释有空间。"},{id:"sm_heaven_xieshi",term:"偕逝",pinyin:"xié shì",meaning:"一同往、一同流逝。与变化同行，不把自身完全固定在某一状态。"},{id:"sm_heaven_sida",term:"始用四达",pinyin:"shǐ yòng sì dá",meaning:"开始被任用而通达四方等，训释有差异。下接爵禄并至，整体描写得用、显达与外在增益。"},{id:"sm_heaven_za wai",term:"吾命有在外者也",pinyin:"wú mìng yǒu zài wài zhě yě",meaning:"自身的遭际有取决于外在条件的部分。强调外在所得不能完全据为自身固有，不等于所有行动都无意义。"},{id:"sm_heaven_yier",term:"鷾鸸",pinyin:"yì ér",meaning:"鸟名，传统多释为燕子，并非只能理解成虚构神鸟。寓言突出其择处、警觉而仍在人间生活。"},{id:"sm_heaven_jishi",term:"目之所不宜处不给视",pinyin:"mù zhī suǒ bù yí chǔ bù jǐ shì",meaning:"对不宜停处的地方，不作久视、顾恋等。给常有捷疾之解，整句有训释空间；不宜只按现代给与义理解。"},{id:"sm_heaven_xiren",term:"袭诸人间",pinyin:"xí zhū rén jiān",meaning:"进入、隐处或习处于人间。与畏人对举，说明警觉不必等于完全离开人类生活。社稷存焉尔的具体所指有解释空间。"},{id:"sm_heaven_shan",term:"禅",pinyin:"shàn",meaning:"递变、相代、传递。联系万物变化的连续交替理解，不直接指禅定。"},{id:"sm_heaven_zhengdai",term:"正而待之",pinyin:"zhèng ér dài zhī",meaning:"安正自身而应待变化。不等于禁止追问或停止一切行动。"},{id:"sm_heaven_xing",term:"人之不能有天，性也",pinyin:"rén zhī bù néng yǒu tiān, xìng yě",meaning:"人的能力不能占有、支配天，乃其自然限度。句中有的含义有讨论空间，不宜简单改成天人绝无差别。"},{id:"sm_heaven_tishi",term:"晏然体逝而终",pinyin:"yàn rán tǐ shì ér zhōng",meaning:"安然体随变化、流逝，终其生命。体逝不只是在脑中理解流逝，更涉及生命随化而行。"}],k=[{id:"sm_forest_s1",label:"异鹊至栗林：庄周执弹",sentences:[["庄周游于",{text:"雕陵之樊",glossary:"sm_forest_fan"},"，睹一异鹊自南方来者。翼广七尺，目大",{text:"运寸",glossary:"sm_forest_yuncun"},"，",{text:"感周之颡",glossary:"sm_forest_sang"},"，而集于栗林。"],["庄周曰：「此何鸟哉！翼殷不逝，目大不睹。」"],[{text:"蹇裳躩步",glossary:"sm_forest_juebu"},"，执弹而留之。"]]},{id:"sm_forest_s2",label:"蝉、螳螂、异鹊：见得而忘形",sentences:[["睹一蝉方得美荫而忘其身。螳螂",{text:"执翳",glossary:"sm_forest_yi"},"而搏之，见得而忘形。"],["异鹊从而利之，见利而忘其真。"],["庄周怵然曰：「噫！",{text:"物固相累，二类相召",glossary:"sm_forest_xianglei"},"也。」"]]},{id:"sm_forest_s3",label:"庄周反走：虞人逐而谇之",sentences:[["捐弹而反走，",{text:"虞人",glossary:"sm_forest_yuren"},"逐而",{text:"谇",glossary:"sm_forest_sui"},"之。庄周反入，三日不庭。"],[{text:"蔺且",glossary:"sm_forest_linju"},"从而问之：「夫子何为顷间甚不庭乎？」"]]},{id:"sm_forest_s4",label:"守形忘身：入其俗，从其令",sentences:[["庄周曰：「吾",{text:"守形而忘身",glossary:"sm_forest_wangshen"},"，",{text:"观于浊水而迷于清渊",glossary:"sm_forest_qingyuan"},"。"],["且吾闻诸夫子曰：『入其俗，从其令。』"],["今吾游于雕陵而忘吾身，异鹊感吾颡，游于栗林而忘真。栗林虞人",{text:"以吾为戮",glossary:"sm_forest_lu"},"，吾所以不庭也。」"]]}],P=[{id:"sm_forest_fan",term:"雕陵之樊",pinyin:"diāo líng zhī fán",meaning:"雕陵一带的林苑、藩篱或外围。樊的具体所指有差异；此处不坐实地理位置。"},{id:"sm_forest_yuncun",term:"运寸",pinyin:"yùn cùn",meaning:"圆周、圆径约寸等，运常联系圆理解。描写鸟目之大，不宜据此精确复原尺寸。"},{id:"sm_forest_sang",term:"感周之颡",pinyin:"gǎn zhōu zhī sǎng",meaning:"碰触庄周的额头。感：触；颡：额头。"},{id:"sm_forest_juebu",term:"蹇裳躩步",pinyin:"jiǎn cháng jué bù",meaning:"提起衣裳，快步趋前。蹇联系褰、揭起理解；裳指下衣，读 cháng；躩：迅疾举步。"},{id:"sm_forest_yi",term:"执翳",pinyin:"zhí yì",meaning:"凭借遮蔽物、隐蔽自身。翳：遮蔽，不必强定为手执一片树叶。"},{id:"sm_forest_xianglei",term:"物固相累，二类相召",pinyin:"wù gù xiāng lèi, èr lèi xiāng zhào",meaning:"事物相互牵累，两类相互招致。二类的具体所指有不同解释，可联系捕取与被捕取、利与害等考察，不强定为泛指任何不同物种。"},{id:"sm_forest_yuren",term:"虞人",pinyin:"yú rén",meaning:"管理山林、园苑的人。此处为栗林管理者。"},{id:"sm_forest_sui",term:"谇",pinyin:"suì",meaning:"责斥、责骂。不是已经执行了刑罚。"},{id:"sm_forest_linju",term:"蔺且",pinyin:"lìn jū",meaning:"人名，篇中向庄周询问的人，常理解为弟子。且在此读 jū。"},{id:"sm_forest_wangshen",term:"守形而忘身",pinyin:"shǒu xíng ér wàng shēn",meaning:"顾取形体之利，却忘了自身的保全或真实安顿。形与身的具体区分有解释空间，不宜直接等同于身体与灵魂的二分。"},{id:"sm_forest_qingyuan",term:"观于浊水而迷于清渊",pinyin:"guān yú zhuó shuǐ ér mí yú qīng yuān",meaning:"疑难譬喻，常联系逐末失本、能察他物却未察自身等理解。不强定浊水就是外界、清渊就是内在灵魂。"},{id:"sm_forest_lu",term:"以吾为戮",pinyin:"yǐ wú wéi lù",meaning:"把我当作应受责辱、惩处者。戮可联系辱、罪责理解，不等于虞人已经判处庄周死刑。"}],v=[{id:"sm_humble_s1",label:"逆旅二妾：恶者贵而美者贱",sentences:[[{text:"阳子",glossary:"sm_humble_yangzi"},"之宋，宿于",{text:"逆旅",glossary:"sm_humble_nilv"},"。逆旅人有妾二人，其一人美，其一人恶。恶者贵而美者贱。"]]},{id:"sm_humble_s2",label:"美者自美，恶者自恶",sentences:[["阳子问其故，逆旅小子对曰：「其美者",{text:"自美",glossary:"sm_humble_zimei"},"，吾不知其美也；其恶者",{text:"自恶",glossary:"sm_humble_zie"},"，吾不知其恶也。」"]]},{id:"sm_humble_s3",label:"篇末：行贤而去自贤之行",sentences:[["阳子曰：「弟子记之：",{text:"行贤而去自贤之行",glossary:"sm_humble_xingxian"},"，安往而不爱哉！」"]]}],w=[{id:"sm_humble_yangzi",term:"阳子",pinyin:"yáng zǐ",meaning:"篇中的论道人物，传统常联系杨朱理解，但具体身份不宜未经辨析便完全坐实。之宋：往宋国。"},{id:"sm_humble_nilv",term:"逆旅",pinyin:"nì lǚ",meaning:"旅舍、客栈。逆有迎接义，旅指行旅者。"},{id:"sm_humble_zimei",term:"自美",pinyin:"zì měi",meaning:"自以为美、以美自居。语境批评以美自高，不等于欣赏自身外貌就是过错。"},{id:"sm_humble_zie",term:"自恶",pinyin:"zì è",meaning:"自知其丑、不以美自高。恶在美丑义读 è。不能据此倡导自我厌恶或要求人因外貌自卑。"},{id:"sm_humble_xingxian",term:"行贤而去自贤之行",pinyin:"xíng xián ér qù zì xián zhī xíng",meaning:"践行贤善，去除自以为贤、以贤自高的做派。前后两个行可分别联系践行与行为理解，通读为 xíng。"}];return(D,n)=>{const j=l("DaoReadingPrelude"),s=l("DaoTextReading"),r=l("DaoKeywordCards"),d=l("DaoLineGuide");return S(),A("div",null,[n[0]||(n[0]=a("",7)),e(j,{title:"先读前五段：从材用困境，到虚己、复朴与真实交往",summary:"山木与雁打破了「无用必能保全」的固定答案；鲁侯与虚舟把问题推进到名位、自我与对抗；北宫奢呈现具体事务中的顺应；两段孔子寓言则转向才德的显露，以及患难中人与人的联结。",points:[{label:"先看",text:"同样是不材，为什么山木得生，雁却被杀？"},{label:"再问",text:"虚己是减少自我执持，还是取消一切行动与关系？"},{label:"最后",text:"林回为何弃璧负子？淡若水的交情，怎样在患难中表现为相收？"}],hint:"当前整理至前五段。后续段落齐全后，再补全篇逻辑链、三问解读与关键词总索引。"}),n[1]||(n[1]=t("h2",{id:"一、山木与雁·材与不材之间",tabindex:"-1"},[i("一、山木与雁·材与不材之间 "),t("a",{class:"header-anchor",href:"#一、山木与雁·材与不材之间","aria-label":'Permalink to "一、山木与雁·材与不材之间"'},"​")],-1)),n[2]||(n[2]=t("h3",{id:"原文",tabindex:"-1"},[i("原文 "),t("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),e(s,{sections:o,glossary:m,"default-mode":"classic","aria-label":"山木·山木与雁 原文"}),n[3]||(n[3]=t("h3",{id:"生僻字词",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"不材",pinyin:["bù","cái"],meaning:"不适于特定用途，不等于生命没有价值。"},{term:"竖子",pinyin:["shù","zǐ"],meaning:"童仆、年轻仆役。"},{term:"请奚杀",pinyin:["qǐng","xī","shā"],meaning:"请问杀哪一只？奚：哪一个。"},{term:"訾",pinyin:["zǐ"],meaning:"非议、诋毁。与誉相对。"},{term:"一龙一蛇",pinyin:["yī","lóng","yī","shé"],meaning:"借龙蛇说明显隐升潜，不固守一种形态。"},{term:"无肯专为",pinyin:["wú","kěn","zhuān","wéi"],meaning:"不固定采用一种做法。"},{term:"以和为量",pinyin:["yǐ","hé","wéi","liàng"],meaning:"以和适协调为衡量尺度。"},{term:"物物而不物于物",pinyin:["wù","wù","ér","bù","wù","yú","wù"],meaning:"应接事物而不反受事物役使。"},{term:"不肖",pinyin:["bù","xiào"],meaning:"不贤、不才。"},{term:"志之",pinyin:["zhì","zhī"],meaning:"记住它。"}]}),n[4]||(n[4]=t("h3",{id:"核心句引读",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"不是选择一种永远安全的属性，而是不固守一种自保答案",subtitle:"山木与雁必须连读：无用可以保全，也可能招祸。",lines:[{text:"此木以不材得终其天年。",tone:"初见",guide:"伐木者不取大木，是因为它不适于所需用途。对取材者而言无用，对树的保全却有意义。但这只是特定处境中的结果，不是「凡无用者都能安全」的普遍定律。《逍遥游》写惠子的大树与无用之地，《人间世》写匠石与栎社树；《山木》则紧接着用雁的遭遇，使无用之用不能被固化成自保口号。"},{text:"昨日山中之木，以不材得终其天年；今主人之雁，以不材死。先生将何处？",tone:"反转",guide:"木不材而未被砍，雁不能鸣而被杀。并置的重点不在证明无用其实都是坏事，而在显示用途标准随处境而变。弟子追问的是：既然材与不材都不能保证安全，人究竟应当怎样处身？故事没有交代庄子预先安排了这两件事，也不必把叙述中的庄子写成突然陷入困惑；反转首先发生在读者与弟子对不材的理解中。"},{text:"周将处乎材与不材之间。材与不材之间，似之而非也，故未免乎累。",tone:"再破",guide:"庄子先提出居于两端之间，又立即限制这一答案。若把不太有用、也不太无用固定成避祸策略，仍然需要不断依外在评判调整自己，仍可能受其拘系。这里可以批评机械折中，却不宜直接定为对儒家中庸的全面批判：原文没有明说中庸。所破的是一条被当作永久保证的处身公式。"},{text:"一龙一蛇，与时俱化，而无肯专为。一上一下，以和为量。",tone:"应变",guide:"龙蛇、上下共同描写显隐升潜的变化。但变化并非任意摇摆：以和为量，为变化保留了和适、协调的尺度。真正的问题不是今天选材、明天选不材，而是能否不以某一种身份或做法锁定自己，在实际情势中应接而不失根本。"},{text:"物物而不物于物，则胡可得而累邪！",tone:"根本",guide:"前后的物有主动与被动的差别：应接事物，而不反受其役使。不能因此把它解释成自我必须绝对控制一切外物；这反而容易形成新的支配执持。与乘道德、万物之祖连读，它强调的是不让名利、用途与毁誉决定自身的全部。免于累的理想，也不应直接改写成现实中永远不会受伤。"},{text:"合则离，成则毁，廉则挫，尊则议，有为则亏，贤则谋，不肖则欺。胡可得而必乎哉！",tone:"无定",guide:"七组句子呈现聚散得失与人际评价中的风险，其中贤则谋、不肖则欺尤其说明两端都不提供必然保证。它们不是严格论证每一次成就必定毁败、每一位贤者必被谋害，更不是说廉直与贤能没有价值。重点在胡可得而必：不能把一项属性当成免患的充分条件。"}]}),n[5]||(n[5]=a("",5)),e(s,{sections:p,glossary:g,"default-mode":"classic","aria-label":"山木·市南宜僚与鲁侯 原文"}),n[6]||(n[6]=t("blockquote",null,[t("p",null,"**校字说明：**来稿「囗惼心」有字形异常，此处暂整理为「褊心」。全篇合并时，建议据项目采用的底本统一校定。")],-1)),n[7]||(n[7]=t("h3",{id:"生僻字词-1",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"市南宜僚",pinyin:["shì","nán","yí","liáo"],meaning:"篇中的论道人物，又称市南子。"},{term:"须臾",pinyin:["xū","yú"],meaning:"极短时间、片刻。"},{term:"丰狐文豹",pinyin:["fēng","hú","wén","bào"],meaning:"毛皮丰美的狐狸、花纹美丽的豹子。"},{term:"罔罗机辟",pinyin:["wǎng","luó","jī","bì"],meaning:"捕猎的网罗与机关陷阱。"},{term:"刳形去皮",pinyin:["kū","xíng","qù","pí"],meaning:"借去形去皮说明卸除名位执持，不是伤身指令。"},{term:"建德之国",pinyin:["jiàn","dé","zhī","guó"],meaning:"寓言中的质朴理想国。"},{term:"大莫之国",pinyin:["dà"," mò","zhī","guó"],meaning:"广大寂漠的境域，指向与道同游。"},{term:"方舟",pinyin:["fāng","zhōu"],meaning:"两舟相并、并联的船。"},{term:"褊心",pinyin:["biǎn","xīn"],meaning:"心胸狭窄。"},{term:"虚己以游世",pinyin:["xū","jǐ","yǐ","yóu","shì"],meaning:"不以自我执持占满自身，在世间应接。"}]}),n[8]||(n[8]=t("h3",{id:"核心句引读-1",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"从保护自己的皮，到解除对皮的执持",subtitle:"虚己不是消失，而是不把名位与争胜当成全部的自己。",lines:[{text:"吾学先王之道，修先君之业……然不免于患，吾是以忧。",tone:"忧患",guide:"鲁侯持续践行所认可的治理之道，却没有免患。市南子指出其除患之术浅，并不必然判定这些实践全部错误。与前段相接，问题在于：一套值得践行的方法，是否被赋予了保证无患的功能？行为有所根据，与处境永远安全，并不是同一件事。"},{text:"其皮为之灾也。今鲁国独非君之皮邪？",tone:"转喻",guide:"狐豹已经藏身、戒备、谨慎觅食，仍因皮毛价值被猎取。鲁国被比作鲁侯之皮，将问题从行为技巧推进到君位与占有：鲁侯所珍视、所依凭的东西，同时也把他置于争夺和牵累之中。但狐豹遭猎不是它们有罪，也不证明受害者的执著造成了全部伤害。寓言是在分析风险所系，而不是为猎害开脱。"},{text:"其民愚而朴，少私而寡欲；知作而不知藏，与而不求其报。",tone:"质朴",guide:"建德之国以劳动、给予、少欲来构成理想生活。愚而朴不是赞美失去理解能力，而是不以机巧争逐。不知藏也不宜直接化为禁止所有储备：这里针对的是占有与积聚在生活中的支配地位。其生可乐，其死可葬，写的是基本生命能够获得安顿，而非无条件免除现实困难。"},{text:"君无形倨，无留居，以为君车。少君之费，寡君之欲，虽无粮而乃足。",tone:"问答",guide:"鲁侯问道路、舟车、邻人与粮食，市南子转向形倨、居处与欲求。两轮问答把地理旅途转成解除执持的旅途。但这不能作为真实旅行不必备粮的建议，也不能说放下执著便会消除所有外在障碍。寓言突出的是：欲求与自高本身，会决定一个人把什么视为不可缺少。"},{text:"有人者累，见有于人者忧。",tone:"关系",guide:"这句话同时检验占有人与被人占有。主动掌握别人，并不必然自由；被他人役属，也容易生忧。可与物物而不物于物相接，但不能把一切人际关系都归成占有。后面的林回负赤子将显示：承担一个人的需要，可以不是利益计算，而是患难中的相收。"},{text:"向也不怒而今也怒，向也虚而今也实。人能虚己以游世，其孰能害之！",tone:"虚舟",guide:"同样被撞，空船没有可责求的操舟者，实船却使人认定对方应当听从、避让，于是转为愤怒。虚舟揭示责任归属与敌意形成的关系，再引向虚己。它不是教人装作无责任的空船，更不是说受害者只要无我就不会被伤害。现代引申可以放在减少争胜、不过度把每次碰撞认成针对自己，同时仍须保留避险、修复与实际责任。"}]}),n[9]||(n[9]=a("",6)),e(s,{sections:_,glossary:h,"default-mode":"classic","aria-label":"山木·北宫奢赋敛为钟 原文"}),n[10]||(n[10]=t("h3",{id:"生僻字词-2",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"赋敛",pinyin:["fù","liǎn"],meaning:"征收、筹集财物，此处为铸钟。"},{term:"县",pinyin:["xuán"],meaning:"通悬，联系钟的悬设理解。"},{term:"一之间",pinyin:["yī","zhī","jiān"],meaning:"疑难语句，常联系专一、不杂机巧理解。"},{term:"侗",pinyin:["tóng"],meaning:"无知、未分辨的样子。"},{term:"傥",pinyin:["tǎng"],meaning:"舒放、不拘等，此处词组有训释空间。"},{term:"曲傅",pinyin:["qū","fù"],meaning:"曲折附合、曲从等。傅联系附理解。"},{term:"因其自穷",pinyin:["yīn","qí","zì","qióng"],meaning:"顺循其自身情势，让其自行展开至尽。"},{term:"大涂",pinyin:["dà","tú"],meaning:"大道。涂通途。"}]}),n[11]||(n[11]=t("h3",{id:"核心句引读-2",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"不是没有办事，而是不以设术强行支配",subtitle:"复朴与顺应，发生在具体事务之中。",lines:[{text:"北宫奢为卫灵公赋敛以为钟……三月而成上下之县。",tone:"事务",guide:"前两段谈保全与游世，这一段转到铸钟筹资。它说明不受牵累的理想并不只存在于退隐叙述中，也可以在办事时接受检验。但三月完成是故事呈现的结果，原文没有完整交代筹资制度、民众反应与具体过程，不宜补写为所有人完全自愿、毫无民怨的历史事实。"},{text:"一之间无敢设也。既雕既琢，复归于朴。",tone:"复朴",guide:"庆忌问术，北宫奢先说无敢设，再引复朴。这与《达生》梓庆的何术之有具有结构上的相近：不是停止说明，而是把问题从表面技巧推向更根本的状态。既雕既琢又说明朴并非必然等于未经学习；经历加工，却不困于加工之迹，才是此处值得注意的张力。"},{text:"来者勿禁，往者勿止。",tone:"来往",guide:"不禁止来者，不强留去者，显示他不以一己要求堵塞来往。但原文仍说送往迎来，因此不能把无为概括成完全不迎、不送、不行动。与《应帝王》不将不逆比较时，应辨其具体侧重：这里写事务中的接待与顺势，若镜则写不追执往来。两者可相通，却不能逐字等同。"},{text:"从其强梁，随其曲傅，因其自穷。",tone:"顺势",guide:"面对不同情态，北宫奢不一味硬碰，而顺循其展开。但不宜把这句变成任由强者侵犯弱者的管理原则，也不能补成一套原文未交代的精密操控术。可先把握：不以自己的筹计强制所有人沿同一路线行事，仍需分辨具体条件与行动边界。"},{text:"故朝夕赋敛而毫毛不挫，而况有大涂者乎！",tone:"推广",guide:"毫毛不挫可以联系办事而自身不受损折理解，不必只译作没有任何阻碍。末句由这件有限事务推向大道：若事务中的顺应已有其效，更广大的通达又当如何？它是一种推举，不等于已经提供了适用于所有征税和治理问题的完整方案。"}]}),n[12]||(n[12]=a("",5)),e(s,{sections:y,glossary:u,"default-mode":"classic","aria-label":"山木·孔子与大公任 原文"}),n[13]||(n[13]=t("h3",{id:"生僻字词-3",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"大公任",pinyin:["tài","gōng","rèn"],meaning:"篇中的论道人物，大公常读太公。"},{term:"吊",pinyin:["diào"],meaning:"慰问。"},{term:"恶死",pinyin:["wù","sǐ"],meaning:"厌恶、不愿死亡。"},{term:"翂翐",pinyin:["fēn","zhì"],meaning:"飞行迟缓、舒缓等，训释有差异。"},{term:"绪",pinyin:["xù"],meaning:"余剩。"},{term:"自伐",pinyin:["zì","fá"],meaning:"自我夸耀。"},{term:"削迹捐势",pinyin:["xuē","jì","juān","shì"],meaning:"消减显露形迹，舍去权势。"},{term:"至人不闻",pinyin:["zhì","rén","bù","wén"],meaning:"不以闻达与声名立己。"},{term:"衣裘褐",pinyin:["yì","qiú","hè"],meaning:"穿皮衣、粗布衣；衣作动词。"},{term:"杼栗",pinyin:["zhù","lì"],meaning:"树实，常联系橡实、栗实理解。"}]}),n[14]||(n[14]=t("h3",{id:"核心句引读-3",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"从以才德显人之不足，到入群而不乱群",subtitle:"去功名不是取消能力，而是不靠高显与对比维持自己。",lines:[{text:"子几死乎？……子恶死乎？",tone:"处境",guide:"两问两答使孔子承认自己接近死亡，也不愿死。故事据陈蔡之困的传统展开，但大公任的对话以及后续退居，应按本篇寓言阅读，不把每个细节直接认作历史实录。不死之道也不宜解释成肉身永生，而是避免某些由显露、争逐带来的死患。"},{text:"进不敢为前，退不敢为后；食不敢先尝，必取其绪。",tone:"随群",guide:"意怠不争先，也不脱离群体；相引相援而飞、相近而栖，使其保全依托于与群体相处。不能只把它概括成故意装弱，更不必宣布这是比虚己更高的一层境界。尤其要记得开篇之雁：似无能并非普遍免患保证，意怠的意义在其具体相处方式。"},{text:"直木先伐，甘井先竭。",tone:"显用",guide:"直木与甘井因适于取用而先被消耗。这承接大木、狐豹的意象，但不能读到这里就忘掉不鸣之雁，重新得出有用必死、无用必生。它针对的是显著可取之物所承受的消耗风险，不是全篇已经否定材能。"},{text:"饰知以惊愚，修身以明汙，昭昭乎如揭日月而行。",tone:"对比",guide:"大公任所批评的不只是太优秀，而是智识与修身被用来突出别人的愚与污。问题在于以才德建立压迫性的对比，使自己不断显露于人。这与《达生》扁庆子评孙休的相近语句呼应，但不能因此说学习、修身或公开表达本身就是过错，更不能把别人加害全归罪于被害者太耀眼。"},{text:"孰能去功与名而还与众人！道流而不明居，得行而不名处。",tone:"返常",guide:"去功名不是让已经发生的贡献消失，而是不以贡献与声名永久据位。还与众人把方向从高举自身转到平常相处。道与德仍能流行，说明不居名并非无所作为；更重要的是，行事不必持续依靠我比别人更高来成立。"},{text:"入兽不乱群，入鸟不乱行。鸟兽不恶，而况人乎！",tone:"不扰",guide:"结尾以不扰乱群体描写转变：从显露与对比，到进入而不破坏既有生活。鸟兽不恶构成寓言的推举，不保证现实中任何人都会因此欢迎他。现代引申可关注进入群体时先理解其节奏，不把自己的标准立即强加其上，而不是照字面要求所有人离开朋友、弟子与社会。"}]}),n[15]||(n[15]=a("",6)),e(s,{sections:b,glossary:x,"default-mode":"classic","aria-label":"山木·孔子与子桑雽 原文"}),n[16]||(n[16]=t("blockquote",null,[t("p",null,"**阅读说明：**本段的「假人之亡」「无挹于前」「真泠禹」等有训释或异文问题。正文保留来稿主要文字，不以单一解释掩盖疑难。")],-1)),n[17]||(n[17]=t("h3",{id:"生僻字词-4",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"子桑雽",pinyin:["zǐ","sāng","hù"],meaning:"篇中的论道人物，名字存在字形异文。"},{term:"赤子",pinyin:["chì","zǐ"],meaning:"婴儿。"},{term:"布",pinyin:["bù"],meaning:"财货、货币等。"},{term:"天属",pinyin:["tiān","shǔ"],meaning:"天然亲属联系、自然亲情。"},{term:"相收",pinyin:["xiāng","shōu"],meaning:"相互收容、扶持。"},{term:"醴",pinyin:["lǐ"],meaning:"甜酒。"},{term:"翔佯",pinyin:["xiáng","yáng"],meaning:"从容游行、徘徊。"},{term:"挹",pinyin:["yì"],meaning:"此处有揖让、退抑等解释。"},{term:"缘",pinyin:["yuán"],meaning:"顺循、顺应。"},{term:"率",pinyin:["shuài"],meaning:"循其真实、率真，不是效率之率。"}]}),n[18]||(n[18]=t("h3",{id:"核心句引读-4",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"不是有没有拖累，而是联结凭什么成立",subtitle:"弃璧负子，使材用与占有的讨论转向真实的关怀。",lines:[{text:"吾犯此数患，亲交益疏，徒友益散，何与？",tone:"离散",guide:"前段问如何免患，这一段问患难中为何关系离散。重点从外在危险转向交往的根据。但子桑雽用寓言回答，并没有逐个说明离去者的动机；不能据此断言孔子的每位朋友、弟子都只为名利而来。故事提出一种解释尺度，不是完成了所有人物的心理调查。"},{text:"彼以利合，此以天属也。",tone:"联结",guide:"玉璧很贵，婴儿更需要照料。林回却弃璧负子，显示他的选择不以资产收益或减少负担为唯一尺度。天属首先由天然亲情说明，也引向不把人当作利益工具的关系。它不保证所有血亲都可靠，也不排斥非血缘关系具有真实关怀。"},{text:"以利合者……相弃也；以天属者……相收也。",tone:"患难",guide:"相弃与相收让关系的差异在困境中显露：只依利益成立的结合，可能随利益条件消失而解除；真实关怀则可能在对方更加需要时承担更多。这里不应为抛弃行为开脱，也不必把一切合作、报酬与契约都判成虚假。关键在于利益是否成为对待一个人的唯一根据。"},{text:"君子之交淡若水，小人之交甘若醴。君子淡以亲，小人甘以绝。",tone:"淡交",guide:"淡若水不等于无热情、少联络或不表达爱。与相收连读，淡更涉及不靠利益交换、奉承与浓烈表演维持关系。甘若醴也不是说热烈的友谊必然失败，而是警惕浓甜掩盖了可随时撤回的利益条件。不必用水不会变质、酒必然变酸作解释：那既不是原文论证，也不是可靠的物理事实。"},{text:"绝学捐书，弟子无挹于前，其爱益加进。",tone:"转变",guide:"寓言确实写弃学捐书，不能把动作完全抹去。但在本段结构中，它将师生关系从依学问、身份与拘谨形式维持，转向更真实的亲近。其爱益加进不证明此前所有弟子都没有真情，也不提供废除教育与书籍的普遍命令。所检验的是：学问与形式是否占据了关系本身。"},{text:"形莫若缘，情莫若率。缘则不离，率则不劳。",tone:"顺真",guide:"缘与率分别指向行事的顺循、情感的真实。不是为了保住关系而无条件迁就，也不是以我很率真为由任意伤人。与不求文以待形相接，它强调减少必须以文饰维护自我的负担，让行动与真实感情能够相通。"},{text:"不求文以待形，固不待物。",tone:"不待",guide:"不待物不是不需要饮食、居所与帮助。可理解为不把自身成立完全寄托于外物与文饰：没有那些标志，也不必认定自己与关系全无价值。由此返回前文，君子之交并非没有具体照料，而是不以外在收益作为亲近的唯一条件。"}]}),n[19]||(n[19]=a("",30)),e(s,{sections:c,glossary:f,"default-mode":"classic","aria-label":"山木·庄子过魏王 原文"}),n[20]||(n[20]=t("h3",{id:"生僻字词-5",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"衣大布",pinyin:["yì","dà","bù"],meaning:"穿粗布衣。衣作动词。"},{term:"正絜系履",pinyin:["zhèng","xié","jì","lǚ"],meaning:"整理绳带，系好鞋履；絜的字形与读法宜据底本校定。"},{term:"惫",pinyin:["bèi"],meaning:"困惫、困顿，文中与贫区分。"},{term:"楠梓豫章",pinyin:["nán","zǐ","yù","zhāng"],meaning:"适合猿猴攀援的大木。"},{term:"眄睨",pinyin:["miǎn","nì"],meaning:"窥视、侧目看，语境中联系瞄准。"},{term:"柘棘枳枸",pinyin:["zhè","jí","zhǐ","jǔ"],meaning:"杂木荆棘，不便猿猴施展。"},{term:"悼栗",pinyin:["dào","lì"],meaning:"恐惧战栗。"},{term:"处势不便",pinyin:["chǔ","shì","bù","biàn"],meaning:"所处条件不利于发挥。"},{term:"昏上乱相",pinyin:["hūn","shàng","luàn","xiàng"],meaning:"昏庸的君主、乱政的相臣。"},{term:"徵",pinyin:["zhēng"],meaning:"证据、明证。"}]}),n[21]||(n[21]=t("h3",{id:"核心句引读-5",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"贫困不等于才德衰败，施展也不能脱离处境",subtitle:"腾猿筋骨未变，换了环境，却不能同样自在。",lines:[{text:"贫也，非惫也。士有道德不能行，惫也。",tone:"辨别",guide:"魏王由破衣破鞋判断庄子惫，庄子首先拒绝把贫困外貌当成才德困败的直接证明。他将贫与道德不能行区分：前者是生活条件，后者涉及其道无法施展。但下文又说处于昏上乱相而欲无惫不可得，因此不能把全段概括成庄子宣称自己内在永远不惫。它同时辨明外貌误判与现实困局。"},{text:"其得楠梓豫章也，揽蔓其枝而王长其间。",tone:"得势",guide:"大木提供适于攀援的条件，猿猴因而自在活动。能力不是孤立存在的东西：枝条、空间与身体共同构成施展的可能。这可与《达生》的技艺故事连读，但不必称其绝对无敌；神射者不能眄睨是寓言用来突出其自在的夸张。"},{text:"此筋骨非有加急而不柔也，处势不便，未足以逞其能也。",tone:"处境",guide:"猿猴在荆棘中战栗，不是筋骨突然失去柔韧，而是处势不便。这里明确拒绝把表现受限直接归成个体无能。与开篇材用相接，能力、用途与条件须一同考察；但也不能反过来说环境决定一切、行动完全无效。重点在承认施展需要条件。"},{text:"今处昏上乱相之间而欲无惫，奚可得邪？",tone:"政治",guide:"动物譬喻转成对政治环境的直接批评。这句话使全篇不能只谈个人如何去执：暴政与乱政确实可能使有道者受困。顺应、虚己不能替昏上乱相解除责任，也不能被写成受害者必须调整自己以适应一切压迫。"},{text:"此比干之见剖心，徵也夫！",tone:"明证",guide:"比干的传说被用作忠直者在暴政下受害的明证。问题不是比干的才德本身有罪，而是施加伤害的政治处境。前文直木先伐的警示，在这里加入了不可忽略的权力关系：不能把一切祸患都归因于太有用或太耀眼。"}]}),n[22]||(n[22]=a("",8)),e(s,{sections:q,glossary:z,"default-mode":"classic","aria-label":"山木·孔子击木而歌 原文"}),n[23]||(n[23]=t("blockquote",null,[t("p",null,[t("strong",null,"文字说明："),i("「焱氏」「始用四达」「社稷存焉尔」及天人关系的数句，有异文或训释空间。这里保留来稿文字，优先梳理论述关系。")])],-1)),n[24]||(n[24]=t("h3",{id:"生僻字词-6",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"槁木",pinyin:["gǎo","mù"],meaning:"枯木。"},{term:"宫角",pinyin:["gōng","jué"],meaning:"五音中的宫、角，借指通常乐律。"},{term:"犁然",pinyin:["lí","rán"],meaning:"清楚、畅然等，具体训释有差异。"},{term:"穷桎",pinyin:["qióng","zhì"],meaning:"困穷、受拘束。桎本为足械。"},{term:"偕逝",pinyin:["xié","shì"],meaning:"与之同往、随变化流逝。"},{term:"爵禄",pinyin:["jué","lù"],meaning:"爵位与俸禄。"},{term:"鷾鸸",pinyin:["yì","ér"],meaning:"鸟名，传统多释燕子。"},{term:"禅",pinyin:["shàn"],meaning:"递变、相代，不指禅定。"},{term:"正而待之",pinyin:["zhèng","ér","dài","zhī"],meaning:"安正自身而应待变化。"},{term:"晏然体逝",pinyin:["yàn","rán","tǐ","shì"],meaning:"安然体随变化而行。"}]}),n[25]||(n[25]=t("h3",{id:"核心句引读-6",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"损未必夺其安顿，益却可能使人把外物当成自己",subtitle:"人与天一，不是占有天，而是承认自身也在变化之中。",lines:[{text:"有其具而无其数，有其声而无宫角。木声与人声，犁然有当于人之心。",tone:"歌声",guide:"枯木、枯枝与人声构成简朴的歌唱，不拘通常节数与宫角，却契合人心。可与复归于朴相接：表达的真实不必完全依靠规范形式。但原文不证明音乐应取消节奏，也不证明所有无规则声音都比有规则声音更真。这里首先呈现困境中的生命回应。"},{text:"无受天损易，无受人益难。",tone:"损益",guide:"天损与人益不是身体免伤和拒绝一切帮助的简单对照。下文把前者放在与变化偕逝，把后者放在爵禄、不妄取与择处之中。相较于接受不可全控的遭际，面对显达和增益时不将其当作自身固有，可能更难。易难是此处的比较，不是对痛苦者的责备。"},{text:"饥渴寒暑，穷桎不行，天地之行也……与之偕逝。",tone:"随化",guide:"饥渴寒暑与困拘被放入天地运行、万物变化中考察，使人不必把一切遭际理解成专门针对自己的惩罚。但不等于饥饿无需求食、疾病无需医治、拘困无需脱身。臣子的类比在古代政治语境中展开，不能直接转成现代人必须服从一切权力的原则。"},{text:"物之所利，乃非己也，吾命有在外者也。",tone:"外得",guide:"爵位、俸禄与任用有赖外在条件，不能全部当成自身天然所有。所利不是对自身价值的永久认证，失去它也未必证明自身全然失败。君子不盗、贤人不窃又加入取予界限：并非一切好处都应拒绝，而是不将可得之物一律据为己有。"},{text:"其畏人也而袭诸人间。",tone:"择处",guide:"鷾鸸常被解释为燕子。它警觉、避不宜之处，却仍在人间生活，构成避害与共处的张力。这个意象不支持彻底退出所有关系，也不是只凭果实落下就判断物不属于自己。其具体行为与社稷句的解释仍需保留空间。"},{text:"焉知其所终？焉知其所始？正而待之而已耳。",tone:"终始",guide:"万物递变，终始相接，人的认识未必能够穷尽其源流。无始而非卒不能直接译为不存在开始和终结；更适宜联系终始的相续。正而待之是承认认识限度后的处身方向，不是禁止求知，也不是认定追问全无价值。"},{text:"人之不能有天，性也。圣人晏然体逝而终矣！",tone:"天人",guide:"人亦处在自然变化中，却不能把天占有或完全支配。人与天一因此不必理解成所有差异都被取消，而可联系人不把自己立为变化之外的主宰。晏然体逝是生命安然随化，不是只在头脑里理解时间，也不宜据此认定本段已经给出全篇最高境界的等级判定。"}]}),n[26]||(n[26]=a("",8)),e(s,{sections:k,glossary:P,"default-mode":"classic","aria-label":"山木·庄周游雕陵 原文"}),n[27]||(n[27]=t("h3",{id:"生僻字词-7",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"樊",pinyin:["fán"],meaning:"林苑、藩篱或外围，具体所指有不同解释。"},{term:"颡",pinyin:["sǎng"],meaning:"额头。"},{term:"蹇裳躩步",pinyin:["jiǎn","cháng","jué","bù"],meaning:"提起衣裳，快步趋前。"},{term:"弹",pinyin:["dàn"],meaning:"弹丸、发弹器具，语境中联系弹弓。"},{term:"翳",pinyin:["yì"],meaning:"遮蔽物、隐蔽。"},{term:"怵然",pinyin:["chù","rán"],meaning:"惊惧、警醒的样子。"},{term:"虞人",pinyin:["yú","rén"],meaning:"管理山林园苑的人。"},{term:"谇",pinyin:["suì"],meaning:"责斥、责骂。"},{term:"蔺且",pinyin:["lìn","jū"],meaning:"篇中向庄周询问的人，常理解为弟子。"},{term:"戮",pinyin:["lù"],meaning:"此处联系责辱、惩处理解，不直接等于处死。"}]}),n[28]||(n[28]=t("h3",{id:"核心句引读-7",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"能看见别人的见利忘身，也可能未察自己正在其中",subtitle:"庄周不是站在牵累之外的旁观者。",lines:[{text:"翼殷不逝，目大不睹。",tone:"异鹊",guide:"翅膀大，却不远飞；眼睛大，却没有察觉周围。异鹊的异常先引起庄周注意，继而使他执弹追近。故事后来揭示：它正被眼前可得之物吸引。感知器官强大，不保证注意力没有被某一利益锁住。"},{text:"蝉方得美荫而忘其身……见得而忘形……见利而忘其真。",tone:"链条",guide:"蝉享荫、螳螂捕蝉、异鹊取螳螂，各自专注眼前所得，却未察自己也可能被取。庄周执弹，又进入相似结构。不能只把前三者写成有执著的对象、把庄周写成完全清醒的观察者；他的自省正承认自己并不在链条之外。"},{text:"物固相累，二类相召也。",tone:"相累",guide:"取与被取、利与害相互招致，是本段可把握的结构。二类的具体所指有不同解释，不必固定成不同物种互相吸引。与开篇物物而不物于物对读，文本把通达的理想放回实际注意与行为中检验：知道一句道理，并不保证每一刻都已经做到。"},{text:"捐弹而反走，虞人逐而谇之。",tone:"反转",guide:"庄周放下弹具、转身离去，却被栗林管理者追责，故事于是超出捕食关系，加入人与地方秩序的关系。他并非只要退出欲望就立即免患；进入园林、持弹活动，也有必须面对的行为边界。"},{text:"吾守形而忘身，观于浊水而迷于清渊。",tone:"自省",guide:"形与身、浊水与清渊的具体解释有空间，可先理解为顾取局部之利却失去对自身处境的照察。不能简单套成外在身体与内在灵魂。三日不庭写失误后的沉潜，不是所有人必须执行的三日修养程序。"},{text:"入其俗，从其令。",tone:"边界",guide:"这句使全篇的顺应不仅关乎心境，也关乎进入一个地方时了解其规则。庄周承认自己忘身、忘真，未妥善应对所入之境。它不是要求无条件服从任何恶俗，但确实提醒：不能以自己懂道为由，认定具体秩序与他人权益都无关紧要。"}]}),n[29]||(n[29]=a("",12)),e(s,{sections:v,glossary:w,"default-mode":"classic","aria-label":"山木·阳子宿逆旅 原文"}),n[30]||(n[30]=t("h3",{id:"生僻字词-8",tabindex:"-1"},[i("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"之宋",pinyin:["zhī","sòng"],meaning:"前往宋国。之作往解。"},{term:"逆旅",pinyin:["nì","lǚ"],meaning:"旅舍、客栈。"},{term:"恶",pinyin:["è"],meaning:"与美相对，指外貌丑，不读厌恶之 wù。"},{term:"自美",pinyin:["zì","měi"],meaning:"以美自居、自高。"},{term:"自恶",pinyin:["zì","è"],meaning:"自知其丑、不以美自高；不倡导自我厌恶。"},{term:"自贤",pinyin:["zì","xián"],meaning:"自以为贤、以贤自高。"},{term:"安往",pinyin:["ān","wǎng"],meaning:"往哪里、无论到哪里。"}]}),n[31]||(n[31]=t("h3",{id:"核心句引读-8",tabindex:"-1"},[i("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"去掉的是自贤，不是贤行",subtitle:"全篇最后没有停在退避，而是明确保留行贤。",lines:[{text:"恶者贵而美者贱。",tone:"反常",guide:"贵贱在此指旅店中的受重视与被轻视，不必直接等于社会等级。外貌条件与实际相处中的评价并不一致，故事借此追问以美自居的作用。叙事使用古代妾室与美丑评价的背景，现代阅读不必认可按外貌排序人的价值。"},{text:"其美者自美，吾不知其美也；其恶者自恶，吾不知其恶也。",tone:"自居",guide:"重点不只是有没有美，而是如何凭美与人相处。自美可能使外貌优势伴随自高，影响他人的整体感受；自恶则被用来反衬不自高。但原文没有详述表演、索取注目等具体行为，这些只能作为引申。也不能要求人否定自己、因外貌自卑，才值得被爱。"},{text:"行贤而去自贤之行，安往而不爱哉！",tone:"收束",guide:"行贤明确保留贤善的实践，去自贤则解除以贤自高的做派。不是不做好事，也不只是做好事而藏住消息：更深的是不靠善行建立我高于人的位置。安往而不爱是寓言的推举，不保证人人喜爱；更不应为了得到喜爱，把不自贤再变成精心经营的人设。"}]}),n[32]||(n[32]=a("",115))])}}});export{N as __pageData,R as default};
